public partial class PlayerWindow:System.Windows.Window{readonly DeviceAuth auth;readonly XtreamItem item;bool paused;int aspect;DateTime opened=DateTime.UtcNow;public PlayerWindow(DeviceAuth a,XtreamItem i){InitializeComponent();auth=a;item=i;NowPlaying.Text=i.Name;Loaded+=(_,__)=>Play();Closing+=(_,__)=>Save();}void Play(){if(item.StreamUrl is null)return;Media.Source=new Uri(item.StreamUrl);Media.Play();}void Pause_Click(object s,System.Windows.RoutedEventArgs e){if(paused)Media.Play();else Media.Pause();paused=!paused;}void Aspect_Click(object s,System.Windows.RoutedEventArgs e){aspect=(aspect+1)%3;Media.Stretch=aspect switch{0=>System.Windows.Media.Stretch.UniformToFill,1=>System.Windows.Media.Stretch.Uniform,_=>System.Windows.Media.Stretch.Fill};}void Full_Click(object s,System.Windows.RoutedEventArgs e)=>ToggleFull();void ToggleFull(){if(WindowStyle==System.Windows.WindowStyle.None){WindowStyle=System.Windows.WindowStyle.SingleBorderWindow;WindowState=System.Windows.WindowState.Normal;}else{WindowStyle=System.Windows.WindowStyle.None;WindowState=System.Windows.WindowState.Maximized;}}void Window_KeyDown(object s,System.Windows.Input.KeyEventArgs e){if(e.Key==System.Windows.Input.Key.Escape&&WindowStyle==System.Windows.WindowStyle.None)ToggleFull();else if(e.Key==System.Windows.Input.Key.Space)Pause_Click(s,e);else if(e.Key==System.Windows.Input.Key.F11)ToggleFull();}void Media_Opened(object s,System.Windows.RoutedEventArgs e){}void Media_Ended(object s,System.Windows.RoutedEventArgs e)=>Save();void Save(){long dur=Media.NaturalDuration.HasTimeSpan?(long)Media.NaturalDuration.TimeSpan.TotalMilliseconds:0;long pos=(long)Media.Position.TotalMilliseconds;PlayerStateStore.AddRecent(auth,PlaylistSelectionStore.Load(),new(item.Kind,item.Name,item.Group,item.Image,item.StreamUrl,pos,dur,DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()));}}
